import { createClient } from "@supabase/supabase-js";

/**
 * "Server-side helper" as commonly generated by AI tools: a single service-role client used
 * whenever a route needs data the cookie client might not return. The service role bypasses
 * Row Level Security entirely.
 */
export function createAdminClient() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
    { auth: { persistSession: false } },
  );
}
